@startuml

class OOBank {}

class OrganizationalUnit {}

class Division extends OrganizationalUnit {}

class Subdivision extends OrganizationalUnit {}

class Branch extends Subdivision {
  + address
  + number
}

class Employee {}

class Manager {}

class Customer {}

class Account {
  + accountNumber
  + balance
  + creditOrOverdraftLimit
}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class CreditCard {}

OOBank "1" -- "*" Division
Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
Division "1" -- "*" Employee
Division "1" -- "0..1" Manager
Subdivision "1" -- "*" Employee
Branch "1" -- "*" Account
Branch "1" -- "*" Customer
Customer "1..2" -- "*" Account
Customer "0..1" -- "1" Employee : personalBanker
Account "*" -- "1" AccountType
CreditCard "1" -- "*" CreditCardAccount

@enduml

